from django.contrib.sitemaps.views import sitemap
from django.contrib.syndication.views import Feed
from .sitemaps import PostSitemap

class LatestPostsFeed(Feed):
    title = "Example blog"
    link = "/blog/"
    description = "Latest published posts"

    def items(self):
        return Post.objects.filter(published=True)[:20]

    def item_title(self, item):
        return item.title

    def item_description(self, item):
        return item.summary

    def item_pubdate(self, item):
        return item.published_at

urlpatterns += [
    path("sitemap.xml", sitemap, {"sitemaps": {"posts": PostSitemap}}),
    path("blog/feed/", LatestPostsFeed()),
]

from django.core.cache import cache

def cached_sitemap(request):
    xml = cache.get("sitemap:posts")
    if xml is None:
        xml = render_sitemap()
        cache.set("sitemap:posts", xml, 60 * 30)
    return HttpResponse(xml, content_type="application/xml")

