from django.core.exceptions import ValidationError
from django.core.validators import MinValueValidator

def validate_even(value):
    if value % 2:
        raise ValidationError("Wpisz liczbę parzystą.")

class Ticket(models.Model):
    seats = models.PositiveIntegerField(
        validators=[MinValueValidator(1), validate_even]
    )

from django.db.models import Q, UniqueConstraint, CheckConstraint

class Booking(models.Model):
    room = models.ForeignKey(Room, on_delete=models.CASCADE)
    starts_at = models.DateTimeField()
    ends_at = models.DateTimeField()

    class Meta:
        constraints = [
            UniqueConstraint(fields=["room", "starts_at"], name="unique_slot"),
            CheckConstraint(check=Q(ends_at__gt=models.F("starts_at")), name="end_after_start"),
        ]

from django.core.checks import Error, Warning, register

@register()
def check_payment_key(app_configs, **kwargs):
    from django.conf import settings
    if not getattr(settings, "PAYMENT_SECRET", ""):
        return [Error("PAYMENT_SECRET is not set.", id="shop.E001")]
    if settings.DEBUG and settings.PAYMENT_SECRET.startswith("test_"):
        return [Warning("Test payment key used with DEBUG=True.", id="shop.W001")]
    return []

